xml.Script:
        Color := '404040';

        R := 0.7;

        // get Cx Cy Cz
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        // cuts
        for i := 0 to 11 do
          RC[ i] := R * (0.69 + 0.01 * i);

        // randomize cuts
        for i := 0 to 10 do begin
            i1 := Random(12);
            i2 := Random(12);
            RCX := RC[i1];
            RC[i1] := RC[i2];
            RC[i2] := RCX;
        end;

        // layers
        for i := 0 to 3 do
            D[i] := R * (0.5 + 0.05 * i);
